class Block:
    """Minecraft block description. Can be sent to Minecraft.setBlock/s.

    ``id`` is either a classic numeric block id (int, pre-1.13 protocol) or a
    modern block name (str, e.g. "copper_block"). Both travel over the same
    wire protocol; the server decides how to resolve them, so existing lessons
    that use numeric ids keep working unchanged while new lessons can use the
    full 1.20.1 block palette by name."""
    def __init__(self, id, data=0):
        self.id = id
        self.data = data

    def __cmp__(self, rhs):
        return hash(self) - hash(rhs)

    def __eq__(self, rhs):
        return self.id == rhs.id and self.data == rhs.data

    def __hash__(self):
        if isinstance(self.id, str):
            return hash((self.id, self.data))
        return (self.id << 8) + self.data

    def withData(self, data):
        return Block(self.id, data)

    def __iter__(self):
        """Allows a Block to be sent whenever id [and data] is needed"""
        return iter((self.id, self.data))

    def __repr__(self):
        return "Block(%r, %r)" % (self.id, self.data)

