# ---------------------------------------------------------------------------
# Modern blocks (1.13 - 1.20.1) addressed by name. These never had a numeric
# id; the server resolves the name via Bukkit's Material lookup. Use exactly
# like any other block constant: mc.setBlock(x, y, z, block.COPPER_BLOCK)
# ---------------------------------------------------------------------------

def _named(name):
    """Modern block referenced by its 1.20.1 Material name."""
    return Block(name)

